const REMOVED_SET: ReadonlySet<string> = new Set(REMOVED_PATHS);

/**
 * Normalise a path or absolute URL to a bare apex pathname:
 * strips the origin, query and fragment, and removes a trailing
 * slash (except for the root path).
 */
export function normalizePathname(input: string): string {
  let p = input;
  const schemeEnd = p.indexOf('://');
  if (schemeEnd >= 0) {
    const slash = p.indexOf('/', schemeEnd + 3);
    p = slash >= 0 ? p.slice(slash) : '/';
  }
  const cut = p.search(/[?#]/);
  if (cut >= 0) p = p.slice(0, cut);
  if (!p.startsWith('/')) p = `/${p}`;
  if (p.length > 1 && p.endsWith('/')) p = p.slice(0, -1);
  return p;
}

/** Step 4 classification for a path, or undefined if unclassified. */
export function getPolicyClass(input: string): PolicyClass | undefined {
  return CLASSIFIED_PATHS[normalizePathname(input)];
}

/** True when the path is classified REMOVE in the Step 4 policy. */
export function isRemoved(input: string): boolean {
  return REMOVED_SET.has(normalizePathname(input));
}

/**
 * True when the path may be presented to search engines as an
 * indexable apex URL. Under the D-016 defaulting rule this is
 * exactly "not classified REMOVE": data-driven families are
 * enumerated unless removed, and route sections of the sitemap
 * are explicit lists filtered through this helper.
 */
export function isIndexable(input: string): boolean {
  return !isRemoved(input);
}
